// Bildet die Workshop-Antwort für index.html. Greift Trainer[0]
// (SeaTable-Multi-Link) und joint Name + FotoUrl.
//
// Response-Shape:
//   { id, Name, Datum, LifoVerwendet, TrainerName, TrainerPhoto,
//     FormUrl, QrCodeImage }
//
// FormUrl + QrCodeImage sind SeaTable-Formelspalten (siehe
// get-active-workshops.json für Details).

const workshopResp = $('Query Workshop by ID').first().json;
const trainersResp = $('Query Trainer (SQL)').first().json;

const workshop = (workshopResp.results || [])[0];
const trainers = (trainersResp.results || []);

if (!workshop) {
  // Sollte nicht passieren — wir sind in der false-Branch des IF.
  // Defensive: 404-äquivalent als Fehler werfen.
  throw new Error('workshop_not_available');
}

// SeaTable-Link-Spalten kommen je nach Version als string[] oder als
// [{row_id, display_value}, …]. Beide Formen abfangen.
function firstLinkedId(link) {
  if (!Array.isArray(link) || link.length === 0) return null;
  const first = link[0];
  if (typeof first === 'string') return first;
  if (first && typeof first === 'object' && first.row_id) return first.row_id;
  return null;
}

const trainerId = firstLinkedId(workshop.Trainer);
const trainer   = trainerId ? trainers.find(t => t._id === trainerId) : null;

return [{
  json: {
    id:            workshop._id,
    Name:          workshop.Name || '',
    Datum:         workshop.Datum || '',
    LifoVerwendet: !!workshop.LifoVerwendet,
    TrainerName:   trainer ? (trainer.Name || '') : '',
    TrainerPhoto:  trainer ? (trainer.FotoUrl || '') : '',
    FormUrl:       workshop.FormUrl || '',
    QrCodeImage:   workshop.QrCodeImage || ''
  }
}];
